const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));document.querySelectorAll('[data-filter]').forEach(b=>{b.setAttribute('aria-pressed',b.classList.contains('active'));b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});document.querySelectorAll('.product').forEach(p=>p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter)})});document.querySelectorAll('[data-product]').forEach(a=>a.addEventListener('click',()=>document.querySelector('select').value=a.dataset.product));document.querySelector('#brief').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const text=`ЕМК — Екатеринбургские металлические конструкции\nОписание проекта\n\nИмя: ${d.get('name')}\nКонструкция: ${d.get('product')}\n\nЗадача:\n${d.get('details')}\n\nЭто описание не отправлено производителю.`;const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='EMK-project.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Описание скачано. Передайте файл выбранному производителю.'});
const detail=document.querySelector('.detail-image');let queued=false;function glint(){queued=false;if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const rect=detail.getBoundingClientRect();if(rect.top<innerHeight&&rect.bottom>0){const p=(innerHeight-rect.top)/(innerHeight+rect.height);detail.style.setProperty('--glint',`${-60+p*120}%`)}}addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(glint)}},{passive:true});glint();
